# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">03</span><span class="sec-icon">📥</span><h2>Three ways to load files</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">SQL</span><button class="copy" type="button">copy</button></div><pre><span style="color: #8B949E; font-style: italic">-- 1) Batch: CTAS + read_files()  → re-reads everything every time</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">REPLACE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_users</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span>
# MAGIC <span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_files(</span><span style="color: #A5D6FF">'/Volumes/shop/raw/users/'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">format</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'parquet'</span><span style="color: #E6EDF3">);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #8B949E; font-style: italic">-- 2) Incremental batch: COPY INTO  → idempotent, already-loaded files are skipped</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">IF</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">NOT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">EXISTS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_sales;</span>
# MAGIC <span style="color: #FF7B72">COPY</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">INTO</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_sales</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'/Volumes/shop/raw/sales/'</span>
# MAGIC <span style="color: #E6EDF3">FILEFORMAT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">PARQUET</span>
# MAGIC <span style="color: #E6EDF3">COPY_OPTIONS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">(</span><span style="color: #A5D6FF">'mergeSchema'</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'true'</span><span style="color: #E6EDF3">);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #8B949E; font-style: italic">-- 3) Incremental: streaming table + Auto Loader  → recommended</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">REFRESH</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAMING</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_orders</span>
# MAGIC <span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_files(</span><span style="color: #A5D6FF">'/Volumes/shop/raw/orders/'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">format</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'json'</span><span style="color: #E6EDF3">);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #E6EDF3">REFRESH</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAMING</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_orders;</span><span style="color: #6E7681">   </span><span style="color: #8B949E; font-style: italic">-- pick up new files</span></pre></div>
