# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">04</span><span class="sec-icon">🏷️</span><h2>Traceability: metadata columns</h2></div><p>Every file source exposes a hidden <code>_metadata</code> column. Select it explicitly when you load:</p>
# MAGIC <div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">SQL</span><button class="copy" type="button">copy</button></div><pre><span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">REPLACE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_users</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span>
# MAGIC <span style="color: #FF7B72">SELECT</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #E6EDF3">,</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #FF7B72">cast</span><span style="color: #E6EDF3">(from_unixtime(user_first_touch_timestamp</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">/</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">1000000</span><span style="color: #E6EDF3">)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">DATE)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">first_touch_date,</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">_metadata.file_name</span><span style="color: #6E7681">              </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">source_file,</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #E6EDF3">_metadata.file_modification_time</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">file_modified_at,</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #FF7B72">current_timestamp</span><span style="color: #E6EDF3">()</span><span style="color: #6E7681">              </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">ingested_at</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_files(</span><span style="color: #A5D6FF">'/Volumes/shop/raw/users/'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">format</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'parquet'</span><span style="color: #E6EDF3">);</span></pre></div>
# MAGIC <p>This tells you <strong>which file</strong> a row came from and <strong>when</strong> it was loaded. That's essential for debugging and for reprocessing.</p>
# MAGIC </div>

