# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">06</span><span class="sec-icon">🧩</span><h2>JSON and semi-structured data</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">SQL</span><button class="copy" type="button">copy</button></div><pre><span style="color: #8B949E; font-style: italic">-- JSON files → table (nested fields become STRUCT / ARRAY)</span>
# MAGIC <span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_files(</span><span style="color: #A5D6FF">'/Volumes/shop/raw/events/'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">format</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'json'</span><span style="color: #E6EDF3">);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #8B949E; font-style: italic">-- A JSON *string* column (e.g. Kafka value, after unbase64 + cast to STRING):</span>
# MAGIC <span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">value:device,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">value:items[</span><span style="color: #A5D6FF">0</span><span style="color: #E6EDF3">].sku::int</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_kafka;</span><span style="color: #6E7681">               </span><span style="color: #8B949E; font-style: italic">-- colon syntax</span>
# MAGIC <span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">from_json(value,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">schema_of_json(</span><span style="color: #A5D6FF">'&lt;sample json&gt;'</span><span style="color: #E6EDF3">))</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">v</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_kafka;</span><span style="color: #6E7681"> </span><span style="color: #8B949E; font-style: italic">-- → STRUCT</span>
# MAGIC <span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">parse_json(value)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">v</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">bronze_kafka;</span><span style="color: #6E7681">                               </span><span style="color: #8B949E; font-style: italic">-- → VARIANT</span></pre></div>
# MAGIC <div class="tbl"><table>
# MAGIC <thead>
# MAGIC <tr>
# MAGIC <th>Need</th>
# MAGIC <th>Use</th>
# MAGIC </tr>
# MAGIC </thead>
# MAGIC <tbody>
# MAGIC <tr>
# MAGIC <td>Quick extraction from a JSON string</td>
# MAGIC <td><code>col:field.subfield</code>, cast with <code>::type</code></td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td>Typed nested columns</td>
# MAGIC <td><code>from_json(col, schema)</code> → STRUCT, then <code>select v.*</code> to flatten</td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td>Flexible, evolving schema, fast queries</td>
# MAGIC <td><strong><code>VARIANT</code></strong> via <code>parse_json()</code></td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td>One row per array element</td>
# MAGIC <td><code>explode()</code> / <code>explode_outer()</code></td>
# MAGIC </tr>
# MAGIC <tr>
# MAGIC <td>XML (appendix)</td>
# MAGIC <td><code>read_files(..., format =&gt; 'xml', rowTag =&gt; 'book')</code></td>
# MAGIC </tr>
# MAGIC </tbody>
# MAGIC </table></div>
# MAGIC </div>

